from lumen import LumenClient, TaskCreate
import httpx
calls=[]
def handler(req):
    calls.append(len(__import__('json').loads(req.content)['tasks']))
    return httpx.Response(207, json={'results': []})
def gen():
    for i in range(250000):
        yield TaskCreate(str(i), {})
with LumenClient('k', transport=httpx.MockTransport(handler)) as c:
    try:
        c.tasks.batch_create('p', gen())
    except MemoryError:
        print('memoryerror')
